const NAV = [
  { label: "Services", href: "#services" },
  { label: "Work", href: "#work" },
  { label: "Reviews", href: "#reviews" },
  { label: "Contact", href: "#contact" },
]

export default function Section() {
  return (
    <Business>
      {b => (
        <header
          id="top"
          className="sticky top-0 z-40 w-full bg-surface border-b border-border-default"
        >
          <div className="mx-auto flex h-16 max-w-6xl items-center justify-between gap-4 px-4 sm:px-6 md:grid md:h-[72px] md:grid-cols-3 lg:px-8">
            <Link
              href="#top"
              className="flex min-h-11 min-w-0 items-center gap-3 text-foreground"
            >
              {b.logo ? (
                <span className="block w-9 shrink-0 overflow-hidden rounded-sm">
                  <Image src={b.logo} alt={b.name} aspect="1:1" fit="contain" sizes="36px" priority />
                </span>
              ) : (
                <span
                  aria-hidden="true"
                  className="flex h-9 w-9 shrink-0 items-center justify-center rounded-sm border border-border-default font-display text-base font-semibold tracking-tight text-foreground"
                >
                  {b.initial}
                </span>
              )}
              <span className="flex min-w-0 flex-col leading-tight">
                <span className="truncate font-display text-base font-semibold tracking-tight sm:text-lg">
                  {b.name}
                </span>
                {b.profession && (
                  <span className="hidden truncate text-[11px] uppercase tracking-[0.18em] text-foreground-muted lg:block">
                    {b.profession}
                  </span>
                )}
              </span>
            </Link>

            <nav
              aria-label="Sections"
              className="hidden items-center justify-center gap-1 md:flex"
            >
              {NAV.map((n, i) => (
                <Link
                  key={i}
                  href={n.href}
                  className="flex min-h-11 items-center px-3 text-xs font-medium uppercase tracking-[0.16em] text-foreground-secondary transition-colors hover:text-accent-700"
                >
                  {n.label}
                </Link>
              ))}
            </nav>

            <div className="flex shrink-0 items-center justify-end gap-4">
              {b.hours && (
                <span className="hidden items-center gap-2 text-xs text-foreground-muted xl:flex">
                  <span aria-hidden="true" className="h-1.5 w-1.5 rounded-full bg-accent-700" />
                  <span className="max-w-[12rem] truncate">{b.hours}</span>
                </span>
              )}
              <Link
                href={b.phoneUrl ? b.phoneUrl : b.whatsappUrl ? b.whatsappUrl : "#contact"}
                target={!b.phoneUrl && b.whatsappUrl ? "_blank" : "_self"}
                className="flex h-11 w-11 items-center justify-center gap-2 bg-primary-700 text-white transition-colors hover:bg-primary-800 sm:w-auto sm:px-5"
              >
                <Icon
                  name={b.phoneUrl ? "phone" : b.whatsappUrl ? "message-circle" : "mail"}
                  size="sm"
                  strokeWidth={1.5}
                />
                <span className="sr-only text-xs font-semibold uppercase tracking-[0.16em] sm:not-sr-only">
                  {b.phoneUrl ? "Call now" : b.whatsappUrl ? "WhatsApp" : "Get in touch"}
                </span>
              </Link>
            </div>
          </div>
        </header>
      )}
    </Business>
  )
}
